import heapq

def match(orders):
    trades = []
    buy_heap = []   # (-price, seq, id)
    sell_heap = []  # (price, seq, id)
    seq = 0
    info = {}  # id -> {'side','price','qty','active'}

    for order in orders:
        typ = order[0]

        if typ == 'cancel':
            oid = order[1]
            if oid in info:
                info[oid]['active'] = False
            continue

        if typ == 'limit':
            _, oid, side, price, qty = order
        elif typ == 'ioc':
            _, oid, side, price, qty = order
        elif typ == 'market':
            _, oid, side, qty = order
            price = None
        else:
            continue

        info[oid] = {'side': side, 'price': price, 'qty': qty, 'active': True}
        remaining = qty

        if side == 'buy':
            while remaining > 0 and sell_heap:
                sp, sseq, sid = sell_heap[0]
                sinfo = info[sid]
                if not sinfo['active'] or sinfo['qty'] <= 0:
                    heapq.heappop(sell_heap)
                    continue
                if typ != 'market' and sp > price:
                    break
                trade_qty = min(remaining, sinfo['qty'])
                trades.append([oid, sid, sp, trade_qty])
                remaining -= trade_qty
                sinfo['qty'] -= trade_qty
                if sinfo['qty'] == 0:
                    sinfo['active'] = False
                    heapq.heappop(sell_heap)

            info[oid]['qty'] = remaining
            if typ == 'limit' and remaining > 0:
                seq += 1
                heapq.heappush(buy_heap, (-price, seq, oid))
            else:
                info[oid]['active'] = False

        else:  # sell
            while remaining > 0 and buy_heap:
                bp_neg, bseq, bid = buy_heap[0]
                bp = -bp_neg
                binfo = info[bid]
                if not binfo['active'] or binfo['qty'] <= 0:
                    heapq.heappop(buy_heap)
                    continue
                if typ != 'market' and bp < price:
                    break
                trade_qty = min(remaining, binfo['qty'])
                trades.append([bid, oid, bp, trade_qty])
                remaining -= trade_qty
                binfo['qty'] -= trade_qty
                if binfo['qty'] == 0:
                    binfo['active'] = False
                    heapq.heappop(buy_heap)

            info[oid]['qty'] = remaining
            if typ == 'limit' and remaining > 0:
                seq += 1
                heapq.heappush(sell_heap, (price, seq, oid))
            else:
                info[oid]['active'] = False

    return trades

